"""Write docs/FINDINGS_DATA.md: every number in docs/REPORT.md comes from this auto-generated file."""

from __future__ import annotations

import json

import pandas as pd

from ..config import ALL_SEASONS, PATHS, PROJECT_ROOT

LABEL = {"season_avg": "Season average", "l10": "Last-10 average", "per_min": "Per-minute x projected minutes",
         "opp_adj": "Opponent-adjusted per-minute", "eb": "Empirical-Bayes rates (closed form)",
         "gbm": "Gradient boosting (LightGBM, Poisson)", "sim_none": "Possession simulation (bottom-up)",
         "sim_team": "Possession simulation (team-constrained)", "topdown": "Team-first reconciliation"}
STATS = ["pts", "reb", "ast", "fg3m", "pra", "stl", "blk", "tov"]


def _table(df: pd.DataFrame, value: str, fmt: str) -> str:
    t = df.pivot(index="model", columns="stat", values=value)
    order = [m for m in LABEL if m in t.index]
    t = t.loc[order, [s for s in STATS if s in t.columns]]
    lines = ["| Model | " + " | ".join(s.upper() for s in t.columns) + " |",
             "|---|" + "---:|" * len(t.columns)]
    best = t.min(axis=0) if value in ("mae", "rmse", "crps", "pit_dev") else None
    for m, row in t.iterrows():
        cells = []
        for s, v in row.items():
            txt = format(v, fmt) if pd.notna(v) else "–"
            if best is not None and pd.notna(v) and abs(v - best[s]) < 1e-12:
                txt = f"**{txt}**"
            cells.append(txt)
        lines.append(f"| {LABEL[m]} | " + " | ".join(cells) + " |")
    return "\n".join(lines)


def write_findings(summ: dict | None = None) -> str:
    summ = summ or json.loads((PATHS.backtest / "summary.json").read_text())
    out = ["# Findings data (auto-generated by `quantlab report`)", "",
           f"Tuning season: {summ['tuning_season']}. Test seasons: {', '.join(summ['test_seasons'])}. "
           "All predictions walk-forward (pregame information only). Bold = best model per statistic.", ""]
    for split in ("test", "tuning"):
        pc = pd.DataFrame(summ[f"players_{split}"])
        n = int(pc["n"].max()) if len(pc) else 0
        out += [f"## Player statistics - {split} ({n:,} player-games, identical across models)", ""]
        for value, title, fmt in (("mae", "MAE", ".3f"), ("rmse", "RMSE", ".3f"), ("crps", "CRPS (lower is better)", ".3f"),
                                  ("pit_dev", "Calibration error: PIT histogram L1 distance from uniform (0 = perfect)", ".3f"),
                                  ("cov80", "80% interval coverage (inclusive ends; discrete stats sit above 80% when calibrated)", ".3f"),
                                  ("bias", "Bias (prediction - actual)", "+.3f")):
            out += [f"### {title}", "", _table(pc, value, fmt), ""]
        mt = pd.DataFrame(summ[f"minutes_{split}"])
        out += ["### Minutes", "", "| Model | MAE | RMSE | Bias | MAE (rotation players) | n |", "|---|---:|---:|---:|---:|---:|"]
        for r in mt.itertuples():
            out.append(f"| {r.model} | {r.mae:.3f} | {r.rmse:.3f} | {r.bias:+.3f} | {r.mae_rotation:.3f} | {r.n:,} |")
        out.append("")
    tm = summ["teams"]
    for split in ("test", "tuning"):
        out += [f"## Team forecasts - {split}", "",
                "| Forecast | Margin MAE | Margin RMSE | Total MAE | Total RMSE | Margin CRPS | Total CRPS | Win log-loss | Win Brier | Games |",
                "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
        names = {"team_model": "Team model (ratings)", "sim_none": "Simulation (bottom-up)",
                 "sim_team": "Simulation (team-constrained)", "blend": "Blend (team model + bottom-up simulation)"}
        for k, v in tm[split].items():
            if isinstance(v, dict) and "margin_rmse" in v:
                out.append(f"| {names[k]} | {v['margin_mae']:.3f} | {v['margin_rmse']:.3f} | {v['total_mae']:.3f} | "
                           f"{v['total_rmse']:.3f} | {v['margin_crps']:.3f} | {v['total_crps']:.3f} | "
                           f"{v['win_logloss']:.4f} | {v['win_brier']:.4f} | {v['games']:,} |")
        bs = tm[split].get("bootstrap_mse_gain_vs_team_model")
        if bs:
            out += ["", "Paired bootstrap over games (2,000 resamples) of the reduction in squared error vs the team model "
                    "(positive = better):", ""]
            for k, v in bs.items():
                out.append(f"* {k.replace('_', ' ')}: {v['mean']:+.2f} (95% CI {v['ci95'][0]:+.2f} to {v['ci95'][1]:+.2f})")
        out.append("")
    out += [f"Blend weight on the team model (chosen on {summ['tuning_season']} by margin + total RMSE): "
            f"**{tm['blend_weight']:.2f}**", ""]
    c = summ.get("cost", {})
    if "us_per_game" in c:
        out += ["## Computational cost", "",
                f"{c['n_sims']:,} simulated games: {c['simulate_s']:.2f} s ({c['us_per_game']:.0f} µs per game, 4 cores) "
                f"+ {c['calibration_s']:.2f} s pilot calibration. Invariants on every simulated game: "
                f"{', '.join(k for k, v in c['invariants'].items() if v and k != 'all')} -> all = {c['invariants']['all']}.", ""]
    out += ["## Data quality", "", "| Season | Games | Usable | Valid lineup time | Minutes within 1 s | PTS exact | All stats exact | +/- exact |",
            "|---|---:|---:|---:|---:|---:|---:|---:|"]
    for s in ALL_SEASONS:
        p = PATHS.processed(s) / "quality.json"
        if p.exists():
            q = json.loads(p.read_text())
            o = q.get("official_box", {})
            f = lambda k: f"{100 * o[k]:.2f}%" if k in o else "n/a"
            out.append(f"| {s} | {q['games']:,} | {q['games_ok']:,} | {100 * q['valid_time_share']:.3f}% | "
                       f"{f('minutes_within_1s')} | {f('pts_exact')} | {f('all_stats_exact')} | {f('plus_minus_exact')} |")
    text = "\n".join(out) + "\n"
    (PROJECT_ROOT / "docs").mkdir(exist_ok=True)
    (PROJECT_ROOT / "docs" / "FINDINGS_DATA.md").write_text(text)
    return text
